/**
 * OUR OWN 10x10 board layout for Five Row. This is NOT the layout of the
 * classic trademarked game; it was generated by
 * scripts/generate-fiverow-board.ts with the constraints described there.
 *
 * Cells are listed row by row, top-left first. 'free' marks the four corner
 * spaces, which count for every team. Every other cell names a card as
 * "rank-suit"; each non-Jack card appears exactly twice, Jacks never.
 *
 * Do not edit by hand and do not regenerate casually: a changed layout
 * breaks saved games and statistics.
 */
import { cardId, type Card, type Rank, type Suit } from './cards.js';
import { FIVEROW_BOARD_SIZE } from './fiverow.js';

export const FREE_SPACE = 'free';
export type BoardCell = string | typeof FREE_SPACE;

// generated by scripts/generate-fiverow-board.ts with seed 20260922 (0 restarts)
export const FIVEROW_BOARD: readonly BoardCell[] = [
  'free', '2-spades', 'A-diamonds', '3-hearts', '10-hearts', '6-hearts', '10-diamonds', '8-diamonds', '2-clubs', 'free',
  '3-diamonds', '7-diamonds', '4-hearts', '3-clubs', 'K-spades', 'K-diamonds', '2-hearts', '4-spades', 'A-spades', 'Q-spades',
  '10-spades', '8-spades', '4-diamonds', 'Q-diamonds', '3-diamonds', 'A-clubs', '10-clubs', '2-diamonds', 'A-hearts', '7-spades',
  '3-spades', '9-hearts', '4-clubs', '5-hearts', '5-clubs', '8-clubs', 'K-clubs', '2-spades', 'K-diamonds', '6-clubs',
  '7-clubs', '6-diamonds', '6-spades', '6-clubs', '9-diamonds', 'Q-spades', '4-hearts', 'K-hearts', '5-hearts', '5-diamonds',
  '3-clubs', '9-clubs', '2-hearts', '9-spades', '7-diamonds', 'Q-clubs', '3-hearts', '7-hearts', '8-hearts', '4-diamonds',
  '5-clubs', '7-hearts', '2-clubs', '9-hearts', '7-spades', '5-spades', '4-clubs', '8-spades', '10-spades', 'Q-hearts',
  '8-clubs', '8-hearts', '8-diamonds', 'Q-hearts', 'A-clubs', '10-hearts', '9-spades', 'A-hearts', '2-diamonds', '6-hearts',
  '6-diamonds', '10-clubs', '5-spades', '9-clubs', 'K-hearts', '6-spades', 'Q-diamonds', '5-diamonds', '10-diamonds', '7-clubs',
  'free', 'Q-clubs', '4-spades', 'A-diamonds', '3-spades', 'A-spades', '9-diamonds', 'K-clubs', 'K-spades', 'free',
];

export const FIVEROW_CELL_COUNT = FIVEROW_BOARD_SIZE * FIVEROW_BOARD_SIZE;

export function cellIndex(row: number, col: number): number {
  return row * FIVEROW_BOARD_SIZE + col;
}

export function cellRowCol(index: number): { row: number; col: number } {
  return { row: Math.floor(index / FIVEROW_BOARD_SIZE), col: index % FIVEROW_BOARD_SIZE };
}

export function isFreeSpace(index: number): boolean {
  return FIVEROW_BOARD[index] === FREE_SPACE;
}

/** Parse a board cell like "10-hearts" back into a Card. */
export function cardFromCellId(id: string): Card {
  const dash = id.lastIndexOf('-');
  return { rank: id.slice(0, dash) as Rank, suit: id.slice(dash + 1) as Suit };
}

const cellsByCard = new Map<string, number[]>();
FIVEROW_BOARD.forEach((cell, index) => {
  if (cell === FREE_SPACE) return;
  const list = cellsByCard.get(cell) ?? [];
  list.push(index);
  cellsByCard.set(cell, list);
});

/** The two board cells showing this card (empty for Jacks). */
export function cellsForCard(card: Card): readonly number[] {
  return cellsByCard.get(cardId(card)) ?? [];
}
